<?php
require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v2.php';$u=api_v2_user('favorites');$uid=(int)$u['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$in=api_input();$bid=(int)($in['business_id']??0);if($bid<1)api_v2_error('business_id required',422);$action=(string)($in['action']??'toggle');$exists=db()->prepare('SELECT id FROM favorite_businesses WHERE user_id=? AND business_id=? LIMIT 1');$exists->execute([$uid,$bid]);$id=$exists->fetchColumn();if($action==='remove'||($action==='toggle'&&$id)){db()->prepare('DELETE FROM favorite_businesses WHERE user_id=? AND business_id=?')->execute([$uid,$bid]);$saved=false;}else{db()->prepare('INSERT IGNORE INTO favorite_businesses(user_id,business_id) VALUES(?,?)')->execute([$uid,$bid]);$saved=true;}api_v2_ok(['saved'=>$saved,'business_id'=>$bid],$uid);}$q=db()->prepare('SELECT b.id,b.name,b.slug,b.address,b.phone,b.whatsapp,b.image,c.name city_name,cat.name category_name,f.created_at saved_at FROM favorite_businesses f JOIN businesses b ON b.id=f.business_id LEFT JOIN cities c ON c.id=b.city_id LEFT JOIN categories cat ON cat.id=b.category_id WHERE f.user_id=? AND b.status=1 ORDER BY f.id DESC LIMIT 200');$q->execute([$uid]);api_v2_ok(['favorites'=>$q->fetchAll()],$uid);
